UPDATE batch.console_ai_monthly_usage
   SET reserved_cost_usd = 0,
       reserved_updated_at = CURRENT_TIMESTAMP,
       updated_at = CURRENT_TIMESTAMP
 WHERE tenant_id = #{tenantId}
   AND billing_month = #{billingMonth}
   AND reserved_cost_usd > 0
   AND reserved_updated_at < #{cutoff}
